import { type ComponentType, type ReactNode, useId } from "react";

/**
 * Official agent marks, normalized to one icon box.
 *
 * Brand marks belong to their owners and are used here to identify the agent a
 * session runs. A brand with a colour keeps it (Claude orange, Kiro purple,
 * Qwen purple, the Gemini gradient); a monochrome brand uses `currentColor` so
 * it stays legible in light, dark and coloured controls. Paths come from the
 * vendors' published marks; update them from the vendor, not by redrawing.
 */
type MarkProps = { size: number };

function Mark({ size, viewBox, children }: MarkProps & { viewBox: string; children: ReactNode }) {
  return (
    <svg
      width={size}
      height={size}
      viewBox={viewBox}
      fill="none"
      aria-hidden="true"
      focusable="false"
    >
      {children}
    </svg>
  );
}

